/* @lc app=leetcode id=3983 lang=kotlin */ class Solution { fun canMakeSubsequence(s: String, t: String): Boolean = (Int.MAX_VALUE / 2).let { INF -> s.runningFold(0) { l, c -> if (l >= INF) INF else t.indexOf(c, l).let { if (it < 0) INF else it + 1 } }.let { L -> s.reversed().runningFold(t.length) { r, c -> t.lastIndexOf(c, r - 1) }.reversed().let { R -> s.indices.any { L[it] < R[it + 1] } } } } }